  public static void validatePresignedHttpRequest(Cloudidentity.PresignedHttpRequest msg)
      throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate method (assert_required)
    if (msg.getMethod().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field method is required");
    }
    // Validate method (assert_max_length: 16)
    if (msg.getMethod().length() > 16) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field method must be at most 16 characters, got: %d", msg.getMethod().length()));
    }
    // Validate url (assert_required)
    if (msg.getUrl().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field url is required");
    }
    // Validate url (assert_max_length: 2048)
    if (msg.getUrl().length() > 2048) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field url must be at most 2048 characters, got: %d", msg.getUrl().length()));
    }
  }

  // ============ Merge ============
  public static Cloudidentity.CloudIdentityProof.Builder mergeCloudIdentityProof(
      Cloudidentity.CloudIdentityProof dst, Cloudidentity.CloudIdentityProof src) {
    Cloudidentity.CloudIdentityProof.Builder builder = dst.toBuilder();
    if (dst.getVendorValue() == 0) {
      builder.setVendorValue(src.getVendorValue());
    }
    if (!dst.hasPresignedRequest() && src.hasPresignedRequest()) {
      builder.setPresignedRequest(src.getPresignedRequest());
    } else if (dst.hasPresignedRequest() && src.hasPresignedRequest()) {
      builder.setPresignedRequest(
          mergePresignedHttpRequest(dst.getPresignedRequest(), src.getPresignedRequest()).build());
    }
    if (dst.getIdentityToken().isEmpty()) {
      builder.setIdentityToken(src.getIdentityToken());
    }
    return builder;
  }

  public static Cloudidentity.PresignedHttpRequest.Builder mergePresignedHttpRequest(
      Cloudidentity.PresignedHttpRequest dst, Cloudidentity.PresignedHttpRequest src) {
    Cloudidentity.PresignedHttpRequest.Builder builder = dst.toBuilder();
    if (dst.getMethod().isEmpty()) {
      builder.setMethod(src.getMethod());
    }
    if (dst.getUrl().isEmpty()) {
      builder.setUrl(src.getUrl());
    }
    if (dst.getHeadersMap().isEmpty()) {
      builder.putAllHeaders(src.getHeadersMap());
    }
    if (dst.getBody().isEmpty()) {
      builder.setBody(src.getBody());
    }
    return builder;
  }

